/**
 * @vitest-environment jsdom
 *
 * #364 recent-projects UX: per-entry 履歴から削除 on the EMPTY list,
 * duplicate-name parent-dir sublines, and the projectOpenFailed card's
 * remove-and-close action. Exercises the real components through
 * ImportScreenBody with a fixture ImportView.
 */

import { act } from "react";
import { createRoot, type Root } from "react-dom/client";
import { afterEach, describe, expect, it, vi } from "vitest";
import { ImportScreenBody, type ImportView } from "./ImportStates";
import { DEFAULT_TRANSCRIPTION_OPTIONS } from "./types";
import type { LoadedAudio } from "./types";
import { ja } from "../strings/ja";
import type { ScreenState } from "../workspace/screen";

(globalThis as Record<string, unknown>).IS_REACT_ACT_ENVIRONMENT = true;

let root: Root | null = null;
let host: HTMLDivElement | null = null;

const NOOP = () => undefined;

function view(overrides: Partial<ImportView>): ImportView {
  return {
    audio: null,
    openingLabel: null,
    openingKind: null,
    issue: null,
    sourceMissing: null,
    recentProjects: [],
    options: DEFAULT_TRANSCRIPTION_OPTIONS,
    onOpenAudio: NOOP,
    onOpenProject: NOOP,
    onRemoveRecent: NOOP,
    onPickRelink: NOOP,
    onDismissError: NOOP,
    onOptionsChange: NOOP,
    ...overrides,
  };
}

async function render(screen: ScreenState, v: ImportView): Promise<void> {
  host = document.createElement("div");
  document.body.appendChild(host);
  root = createRoot(host);
  await act(async () => {
    root!.render(<ImportScreenBody screen={screen} view={v} onTranscribe={NOOP} />);
  });
}

async function click(el: Element): Promise<void> {
  await act(async () => {
    (el as HTMLElement).click();
  });
}

afterEach(async () => {
  if (root) {
    await act(async () => {
      root!.unmount();
    });
  }
  root = null;
  host?.remove();
  host = null;
  document.body.innerHTML = "";
});

const AUDIO: LoadedAudio = {
  ref: { kind: "path", path: "C:\\audio\\take-03.wav", name: "take-03.wav" },
  fileName: "take-03.wav",
  format: "wav",
  sizeBytes: 14_680_064,
  durationSeconds: 600,
  sampleRate: 44_100,
  peaks: [0.2, 0.5, 0.8, 0.4],
  mediaSource: { kind: "blob", blob: new Blob() },
};

function transcribeButton(): HTMLButtonElement | undefined {
  return [...document.querySelectorAll<HTMLButtonElement>("button")].find(
    (b) => b.textContent?.trim() === ja.score.transcribeStart,
  );
}

describe("audioReady selection validation (#346)", () => {
  const options = (s: number, e: number) => ({
    ...DEFAULT_TRANSCRIPTION_OPTIONS,
    range: "selection" as const,
    selectionStartSec: s,
    selectionEndSec: e,
  });

  it("an inverted 選択範囲 disables 採譜を開始 and flags the end field", async () => {
    await render("audioReady", view({ audio: AUDIO, options: options(120, 60) }));
    expect(transcribeButton()?.disabled).toBe(true);
    // The field error lives in the 採譜オプション popover — open it.
    const trigger = [...document.querySelectorAll<HTMLButtonElement>("button")]
      .find((b) => b.textContent?.trim() === ja.import.audioOptions.label);
    expect(trigger).toBeTruthy();
    await click(trigger!);
    await act(async () => {
      await new Promise((r) => setTimeout(r, 20));
    });
    expect(document.body.textContent).toContain(
      ja.import.audioOptions.rangeInvalid,
    );
  });

  it("an equal pair is invalid the same way", async () => {
    await render("audioReady", view({ audio: AUDIO, options: options(60, 60) }));
    expect(transcribeButton()?.disabled).toBe(true);
  });

  it("a valid pair keeps 採譜を開始 enabled", async () => {
    await render("audioReady", view({ audio: AUDIO, options: options(60, 120) }));
    expect(transcribeButton()?.disabled).toBe(false);
  });

  it("全曲 mode ignores the stored seconds entirely", async () => {
    await render(
      "audioReady",
      view({
        audio: AUDIO,
        options: { ...options(120, 60), range: "all" },
      }),
    );
    expect(transcribeButton()?.disabled).toBe(false);
  });
});

describe("EMPTY recents (#364)", () => {
  it("each row offers a keyboard-focusable 履歴から削除 button", async () => {
    const removed: string[] = [];
    await render(
      "empty",
      view({
        recentProjects: [
          { name: "etude", path: "C:\\a\\etude.hornscribe.json", openedAt: 2 },
          { name: "solo", path: "C:\\b\\solo.hornscribe.json", openedAt: 1 },
        ],
        onRemoveRecent: (p) => removed.push(p),
      }),
    );
    const removeButtons = [
      ...document.querySelectorAll<HTMLButtonElement>(".hs-recent__remove"),
    ];
    expect(removeButtons).toHaveLength(2);
    expect(removeButtons[0].getAttribute("aria-label")).toBe(
      ja.import.recent.removeAria("etude"),
    );
    await click(removeButtons[0]);
    expect(removed).toEqual(["C:\\a\\etude.hornscribe.json"]);
  });

  it("duplicate names get a parent-dir subline; unique names do not", async () => {
    await render(
      "empty",
      view({
        recentProjects: [
          { name: "etude", path: "C:\\one\\etude.hornscribe.json", openedAt: 3 },
          { name: "etude", path: "D:\\two\\etude.hornscribe.json", openedAt: 2 },
          { name: "solo", path: "C:\\b\\solo.hornscribe.json", openedAt: 1 },
        ],
      }),
    );
    const dirs = [...document.querySelectorAll(".hs-recent__dir")].map(
      (e) => e.textContent,
    );
    expect(dirs).toEqual(["C:\\one", "D:\\two"]);
  });
});

describe("projectOpenFailed card (#364)", () => {
  it("a failed MRU path offers remove-and-close plus pick-another", async () => {
    const removed: string[] = [];
    const dismissed = vi.fn();
    await render(
      "audioError",
      view({
        issue: {
          kind: "projectOpenFailed",
          fileName: "etude.hornscribe.json",
          path: "C:\\a\\etude.hornscribe.json",
        },
        onRemoveRecent: (p) => removed.push(p),
        onDismissError: dismissed,
      }),
    );
    const labels = [...document.querySelectorAll("button")].map(
      (b) => b.textContent,
    );
    expect(labels).toContain(ja.import.errors.chooseAnother);
    const removeBtn = [...document.querySelectorAll("button")].find(
      (b) => b.textContent === ja.import.errors.removeFromRecent,
    );
    expect(removeBtn).toBeTruthy();
    await click(removeBtn!);
    expect(removed).toEqual(["C:\\a\\etude.hornscribe.json"]);
    expect(dismissed).toHaveBeenCalledOnce();
  });

  it("a byte-open failure has no remove affordance (nothing in the MRU)", async () => {
    await render(
      "audioError",
      view({
        issue: { kind: "projectOpenFailed", fileName: "dropped.hornscribe.json" },
      }),
    );
    const labels = [...document.querySelectorAll("button")].map(
      (b) => b.textContent,
    );
    expect(labels).not.toContain(ja.import.errors.removeFromRecent);
    expect(labels).toContain(ja.import.errors.chooseAnother);
  });
});

/**
 * Import-owned score-region bodies (UI-020; docs/GUI_UX_SPEC.md §3/§4/§20).
 *
 * ScoreWorkspace delegates the import-side machine states here:
 *   empty         → drop headline + 開く CTA + formats + trust + recents
 *   openingAudio  → honest indeterminate progress (§5: no fake %)
 *   audioReady    → file metadata + 採譜を開始 + 採譜オプション popover
 *   audioError    → copy-deck error card (別のファイルを選ぶ / 閉じる)
 *   sourceMissing → 元音源が見つかりません card (音源を指定 / 閉じる)
 *
 * All copy resolves through ja.import / ja.emptyState / ja.score — the
 * copy deck (protocol/copy/ja-JP.json) is the source of truth.
 */
import {
  Dismiss16Regular,
  ErrorCircle24Regular,
  FolderOpen24Regular,
  History24Regular,
  Play24Regular,
  Mic24Regular,
  Speaker2Regular,
} from "@fluentui/react-icons";
import { Checkbox } from "@fluentui/react-components";
import { ja } from "../strings/ja";
import { HsButton } from "../components/primitives/Button";
import { HsNumericField } from "../components/primitives/NumericField";
import { HsPopover } from "../components/primitives/Popover";
import { HsProgress } from "../components/primitives/Progress";
import { HsSelect, type HsSelectOption } from "../components/primitives/Select";
import type { ScreenState } from "../workspace/screen";
import { formatBytes, formatDuration } from "./format";
import { invalidSelectionRange } from "./transcriptionParams";
import type {
  ImportIssue,
  LoadedAudio,
  RecentProjectEntry,
  SourceMissingInfo,
  TranscriptionOptions,
} from "./types";
import { issueText, type CaptureState } from "../capture/controller";

/** Everything the import-owned bodies need — assembled once in App and
 *  handed down through ScoreWorkspace (keeps that shared file's diff small
 *  for the sibling feature teams). */
export interface ImportView {
  audio: LoadedAudio | null;
  openingLabel: string | null;
  openingKind: "audio" | "project" | null;
  /** AUDIO_ERROR card content (no-audio failures). */
  issue: ImportIssue | null;
  /** SOURCE_MISSING context (project + last relink outcome). */
  sourceMissing: SourceMissingInfo | null;
  recentProjects: readonly RecentProjectEntry[];
  options: TranscriptionOptions;
  onOpenAudio(): void;
  onOpenProject(entry: RecentProjectEntry): void;
  /** #364: 履歴から削除 — drops the path from the MRU (list entries and
   *  the projectOpenFailed card both use it). Never touches the file. */
  onRemoveRecent(path: string): void;
  onPickRelink(): void;
  onDismissError(): void;
  onOptionsChange(next: TranscriptionOptions): void;
  /** FEAT-001 (#60): capture controls on the EMPTY state. */
  captureState?: CaptureState | null;
  onStartCapture?(source: "loopback" | "microphone"): void;
}

/** Routes the import-owned screen states to their bodies. */
export function ImportScreenBody({
  screen,
  view,
  onTranscribe,
}: {
  screen: ScreenState;
  view: ImportView;
  onTranscribe(): void;
}) {
  switch (screen) {
    case "empty":
      return <EmptyStateBody view={view} />;
    case "openingAudio":
      return <OpeningAudioBody view={view} />;
    case "audioReady":
      return <AudioReadyBody view={view} onTranscribe={onTranscribe} />;
    case "audioError":
      return <AudioErrorBody view={view} />;
    case "sourceMissing":
      return <SourceMissingBody view={view} />;
    default:
      return null;
  }
}

/* ------------------------------ EMPTY (§3) ------------------------------ */

function EmptyStateBody({ view }: { view: ImportView }) {
  return (
    <div className="hs-empty">
      <p className="hs-empty__title">{ja.emptyState.title}</p>
      <p className="hs-empty__or">{ja.emptyState.or}</p>
      <HsButton
        variant="primary"
        size="large"
        icon={<FolderOpen24Regular />}
        onClick={view.onOpenAudio}
      >
        {ja.emptyState.open}
      </HsButton>
      <p className="hs-empty__formats">{ja.emptyState.formats}</p>
      {/* FEAT-001: 録音による取り込み — ファイルを持たない入力経路。 */}
      {view.onStartCapture ? (
        <div className="hs-empty__capture">
          <p className="hs-empty__capture-title">
            {ja.emptyState.captureTitle}
          </p>
          <div className="hs-empty__capture-actions">
            <HsButton
              variant="secondary"
              icon={<Speaker2Regular />}
              disabled={view.captureState?.phase === "recording"}
              onClick={() => view.onStartCapture!("loopback")}
            >
              {ja.emptyState.captureLoopback}
            </HsButton>
            <HsButton
              variant="secondary"
              icon={<Mic24Regular />}
              disabled={view.captureState?.phase === "recording"}
              onClick={() => view.onStartCapture!("microphone")}
            >
              {ja.emptyState.captureMic}
            </HsButton>
          </div>
          <p className="hs-empty__capture-hint">
            {ja.emptyState.captureHint}
          </p>
          {/* 録音開始の失敗(デバイス無し等)はここに表示する —
              ステータス行だけでは EMPTY 画面で見落とされる。 */}
          {view.captureState?.phase === "error" &&
          view.captureState.issue ? (
            <p className="hs-empty__capture-error" role="alert">
              {issueText(view.captureState.issue)}
            </p>
          ) : null}
        </div>
      ) : null}
      <p className="hs-empty__privacy">{ja.emptyState.privacy}</p>
      {/* §3: 履歴がある場合のみ「最近使ったプロジェクト」 */}
      <RecentProjectList view={view} />
    </div>
  );
}

/* --------------------------- OPENING_AUDIO --------------------------- */

/** §3 recents list — per-row 履歴から削除 (#364); duplicate names get a
 *  parent-dir subline so same-named projects stay distinguishable. Rows
 *  are plain <button>s: keyboard focus + Enter/Space just work. */
function RecentProjectList({ view }: { view: ImportView }) {
  if (view.recentProjects.length === 0) return null;
  const nameCounts = new Map<string, number>();
  for (const e of view.recentProjects) {
    nameCounts.set(e.name, (nameCounts.get(e.name) ?? 0) + 1);
  }
  return (
    <div
      className="hs-recent"
      role="group"
      aria-label={ja.import.recent.title}
    >
      <p className="hs-recent__title">{ja.import.recent.title}</p>
      <ul className="hs-recent__list">
        {view.recentProjects.map((entry) => {
          const dir =
            (nameCounts.get(entry.name) ?? 0) > 1
              ? parentDir(entry.path)
              : null;
          return (
            <li key={entry.path} className="hs-recent__row">
              <button
                type="button"
                className="hs-recent__item"
                title={entry.path}
                aria-label={ja.import.recent.openAria(entry.name)}
                onClick={() => view.onOpenProject(entry)}
              >
                <History24Regular aria-hidden="true" />
                <span className="hs-recent__text">
                  <span className="hs-recent__name">{entry.name}</span>
                  {dir ? (
                    <span className="hs-recent__dir">{dir}</span>
                  ) : null}
                </span>
              </button>
              <button
                type="button"
                className="hs-recent__remove"
                title={ja.import.recent.removeTitle}
                aria-label={ja.import.recent.removeAria(entry.name)}
                onClick={() => view.onRemoveRecent(entry.path)}
              >
                <Dismiss16Regular aria-hidden="true" />
              </button>
            </li>
          );
        })}
      </ul>
    </div>
  );
}

/** Containing directory of an MRU path (either separator) — rendered
 *  only when two entries share a name (#364 disambiguation). */
function parentDir(path: string): string {
  const i = Math.max(path.lastIndexOf("\\"), path.lastIndexOf("/"));
  return i > 0 ? path.slice(0, i) : "";
}

function OpeningAudioBody({ view }: { view: ImportView }) {
  const title =
    view.openingKind === "project"
      ? ja.import.opening.project
      : ja.import.opening.audio;
  return (
    <div className="hs-empty hs-opening" role="status">
      <p className="hs-opening__title">{title}</p>
      {/* §5: indeterminate — decode time is not honestly predictable. */}
      <HsProgress label={title} className="hs-opening__progress" />
      {view.openingLabel ? (
        <p className="hs-opening__name">{view.openingLabel}</p>
      ) : null}
    </div>
  );
}

/* --------------------------- AUDIO_READY (§4) --------------------------- */

const TEMPO_OPTIONS: readonly HsSelectOption[] = [
  { value: "auto", label: ja.import.audioOptions.tempoAuto },
  { value: "manual", label: ja.import.audioOptions.tempoManual },
];
const METER_OPTIONS: readonly HsSelectOption[] = [
  { value: "auto", label: ja.import.audioOptions.meterAuto },
  { value: "4/4", label: "4/4" },
  { value: "3/4", label: "3/4" },
  { value: "6/8", label: "6/8" },
  { value: "2/4", label: "2/4" },
  { value: "5/4", label: "5/4" },
  { value: "7/8", label: "7/8" },
  { value: "9/8", label: "9/8" },
  { value: "12/8", label: "12/8" },
];
const MIN_DURATION_OPTIONS: readonly HsSelectOption[] = [
  { value: "8", label: ja.import.audioOptions.minDuration8 },
  { value: "16", label: ja.import.audioOptions.minDuration16 },
  { value: "32", label: ja.import.audioOptions.minDuration32 },
];
const TRIPLET_OPTIONS: readonly HsSelectOption[] = [
  { value: "auto", label: ja.import.audioOptions.tripletsAuto },
  { value: "allow", label: ja.import.audioOptions.tripletsAllow },
  { value: "none", label: ja.import.audioOptions.tripletsNone },
];
const SIMPLICITY_OPTIONS: readonly HsSelectOption[] = [
  { value: "standard", label: ja.import.audioOptions.simplicityStandard },
  { value: "simple", label: ja.import.audioOptions.simplicitySimple },
  { value: "detailed", label: ja.import.audioOptions.simplicityDetailed },
];
const TEXTURE_OPTIONS: readonly HsSelectOption[] = [
  { value: "auto", label: ja.import.audioOptions.textureAuto },
  { value: "mono", label: ja.import.audioOptions.textureMono },
  { value: "melody", label: ja.import.audioOptions.textureMelody },
  { value: "voices", label: ja.import.audioOptions.textureVoices },
  { value: "chords", label: ja.import.audioOptions.textureChords },
];
const BACKEND_OPTIONS: readonly HsSelectOption[] = [
  { value: "auto", label: ja.import.audioOptions.backendAuto },
  { value: "basicPitch", label: "Basic Pitch" },
  { value: "pyin", label: "pYIN（単音）" },
];
const RANGE_OPTIONS: readonly HsSelectOption[] = [
  { value: "all", label: ja.import.audioOptions.rangeAll },
  // #88: 範囲採譜 — 時刻入力のほか、波形ドラッグでも選べる
  // (WaveformView の onSelect)。「ソロ部分だけ採譜」に対応。
  { value: "selection", label: ja.import.audioOptions.rangeSelection },
];

function AudioReadyBody({
  view,
  onTranscribe,
}: {
  view: ImportView;
  onTranscribe(): void;
}) {
  const { audio, options } = view;
  const set = (patch: Partial<TranscriptionOptions>) =>
    view.onOptionsChange({ ...options, ...patch });
  // #346: an empty/inverted 選択範囲 is a field error, not a silent
  // switch to 全曲採譜 — the field shows the message and 採譜を開始
  // stays disabled until the pair is valid again (a waveform drag or
  // corrected numbers both clear it live).
  const rangeInvalid = invalidSelectionRange(
    options,
    audio?.durationSeconds ?? 0,
  );
  return (
    <div className="hs-empty hs-audio-ready">
      <p className="hs-score__empty-title">{ja.score.empty}</p>
      {audio ? (
        <p className="hs-audio-ready__meta">
          <span className="hs-audio-ready__name">{audio.fileName}</span>
          <span aria-hidden="true">・</span>
          <span>{audio.format.toUpperCase()}</span>
          <span aria-hidden="true">・</span>
          <span>{formatDuration(audio.durationSeconds)}</span>
          <span aria-hidden="true">・</span>
          <span>{formatBytes(audio.sizeBytes)}</span>
        </p>
      ) : null}
      <div className="hs-audio-ready__actions">
        <HsButton
          variant="primary"
          size="large"
          icon={<Play24Regular />}
          disabled={rangeInvalid}
          onClick={onTranscribe}
        >
          {ja.score.transcribeStart}
        </HsButton>
        {/* §4: advanced transcription settings live in the popover next to
            the primary action — hidden by default. */}
        <HsPopover
          ariaLabel={ja.import.audioOptions.label}
          positioning="above"
          trigger={
            <HsButton variant="subtle">
              {ja.import.audioOptions.label}
            </HsButton>
          }
        >
          <div className="hs-audio-options">
            <p className="hs-audio-options__title">
              {ja.import.audioOptions.label}
            </p>
            <HsSelect
              label={ja.import.audioOptions.texture}
              options={TEXTURE_OPTIONS}
              value={options.texture}
              hint={ja.import.audioOptions.textureHint(options.texture)}
              onChange={(v) =>
                set({ texture: v as TranscriptionOptions["texture"] })
              }
            />
            <HsSelect
              label={ja.import.audioOptions.backend}
              options={BACKEND_OPTIONS}
              value={options.backend}
              hint={ja.import.audioOptions.backendHint}
              onChange={(v) =>
                set({ backend: v as TranscriptionOptions["backend"] })
              }
            />
            {/* #187: opt-in vocal isolation — center extraction is a
                heuristic, so it stays a deliberate checkbox rather
                than a default. The engine reports whether it applied
                via a review issue either way. */}
            <Checkbox
              label={ja.import.audioOptions.vocalIsolation}
              checked={options.vocalIsolation}
              disabled={
                options.texture === "voices" ||
                options.texture === "chords"
              }
              onChange={(_e, data) =>
                set({ vocalIsolation: data.checked === true })
              }
            />
            <p className="hs-audio-options__hint">
              {/* #322: voices/chords keep overlapping lines — vocal
                  isolation strips the accompaniment first, so the
                  two options contradict. The checkbox disables and
                  the hint explains why instead of silently ignoring. */}
              {options.texture === "voices" ||
              options.texture === "chords"
                ? ja.import.audioOptions.vocalIsolationPolyphonicHint
                : ja.import.audioOptions.vocalIsolationHint}
            </p>
            <HsSelect
              label={ja.import.audioOptions.tempo}
              options={TEMPO_OPTIONS}
              value={options.tempo}
              onChange={(v) =>
                set({ tempo: v as TranscriptionOptions["tempo"] })
              }
            />
            {options.tempo === "manual" ? (
              <HsNumericField
                label={ja.import.audioOptions.tempoBpm}
                value={options.tempoBpm}
                min={30}
                max={300}
                step={1}
                unit="BPM"
                onChange={(v) => set({ tempoBpm: v })}
              />
            ) : null}
            <HsSelect
              label={ja.import.audioOptions.meter}
              options={METER_OPTIONS}
              value={options.meter}
              onChange={(v) => set({ meter: v })}
            />
            <HsSelect
              label={ja.import.audioOptions.minDuration}
              options={MIN_DURATION_OPTIONS}
              value={options.minDuration}
              onChange={(v) => set({ minDuration: v })}
            />
            <HsSelect
              label={ja.import.audioOptions.triplets}
              options={TRIPLET_OPTIONS}
              value={options.triplets}
              onChange={(v) =>
                set({ triplets: v as TranscriptionOptions["triplets"] })
              }
            />
            <HsSelect
              label={ja.import.audioOptions.simplicity}
              options={SIMPLICITY_OPTIONS}
              value={options.simplicity}
              onChange={(v) =>
                set({ simplicity: v as TranscriptionOptions["simplicity"] })
              }
            />
            <HsSelect
              label={ja.import.audioOptions.range}
              options={RANGE_OPTIONS}
              value={options.range}
              onChange={(v) =>
                set({ range: v as TranscriptionOptions["range"] })
              }
            />
            {options.range === "selection" && audio ? (
              <>
                <HsNumericField
                  label={ja.import.audioOptions.rangeStart}
                  value={options.selectionStartSec}
                  min={0}
                  max={audio.durationSeconds}
                  step={0.5}
                  unit={ja.import.audioOptions.secondsUnit}
                  onChange={(v) => set({ selectionStartSec: v })}
                />
                <HsNumericField
                  label={ja.import.audioOptions.rangeEnd}
                  value={options.selectionEndSec}
                  min={0}
                  max={audio.durationSeconds}
                  step={0.5}
                  unit={ja.import.audioOptions.secondsUnit}
                  error={
                    rangeInvalid ? ja.import.audioOptions.rangeInvalid : undefined
                  }
                  onChange={(v) => set({ selectionEndSec: v })}
                />
              </>
            ) : null}
          </div>
        </HsPopover>
      </div>
    </div>
  );
}

/* ------------------------------ errors (§20) ------------------------------ */

/** Copy-deck error copy per issue kind — shared by the AUDIO_ERROR card
 *  and the modal dialog shown when a re-import fails over a live session. */
export function issueCopy(issue: ImportIssue): {
  title: string;
  body: string;
  fileName?: string;
} {
  switch (issue.kind) {
    case "unsupported":
      return {
        title: ja.import.errors.unsupportedTitle,
        body: ja.import.errors.unsupportedBody,
        fileName: issue.fileName,
      };
    case "openFailed":
      return {
        title: ja.import.errors.openFailedTitle,
        body: ja.import.errors.openFailedBody,
        fileName: issue.fileName,
      };
    case "projectOpenFailed":
      return {
        title: ja.import.errors.projectOpenFailedTitle,
        body: ja.import.errors.projectOpenFailedBody,
        fileName: issue.fileName,
      };
  }
}

function AudioErrorBody({ view }: { view: ImportView }) {
  const issue = view.issue ?? { kind: "openFailed" as const };
  const copy = issueCopy(issue);
  const removablePath =
    issue.kind === "projectOpenFailed" ? issue.path : undefined;
  return (
    <div className="hs-empty hs-error" role="alert">
      <ErrorCircle24Regular
        className="hs-error__icon"
        aria-hidden="true"
      />
      <p className="hs-error__title">{copy.title}</p>
      {copy.fileName ? (
        <p className="hs-error__file">{copy.fileName}</p>
      ) : null}
      <p className="hs-error__body">{copy.body}</p>
      <div className="hs-error__actions">
        {/* The shared picker routes .hornscribe.json back to
            openProject, so this doubles as "open another project" —
            shown on projectOpenFailed too (#364). */}
        <HsButton variant="primary" onClick={view.onOpenAudio}>
          {ja.import.errors.chooseAnother}
        </HsButton>
        {removablePath ? (
          <HsButton
            variant="secondary"
            onClick={() => {
              // One click resolves the dead MRU entry: remove, then
              // close back to the (already refreshed) recent list.
              view.onRemoveRecent(removablePath);
              view.onDismissError();
            }}
          >
            {ja.import.errors.removeFromRecent}
          </HsButton>
        ) : null}
        <HsButton
          variant="secondary"
          onClick={view.onDismissError}
        >
          {ja.import.errors.close}
        </HsButton>
      </div>
    </div>
  );
}

function SourceMissingBody({ view }: { view: ImportView }) {
  const info = view.sourceMissing;
  const mismatch = info?.mismatch === true;
  return (
    <div className="hs-empty hs-error" role="alert">
      <ErrorCircle24Regular
        className="hs-error__icon"
        aria-hidden="true"
      />
      <p className="hs-error__title">
        {mismatch
          ? ja.import.errors.hashMismatchTitle
          : ja.import.errors.sourceMissingTitle}
      </p>
      {info?.project.sourcePath ? (
        <p className="hs-error__file" title={info.project.sourcePath}>
          {ja.import.errors.lastLocation}
          {info.project.sourcePath}
        </p>
      ) : null}
      <p className="hs-error__body">
        {mismatch
          ? ja.import.errors.hashMismatchBody
          : ja.import.errors.sourceMissingBody}
      </p>
      <div className="hs-error__actions">
        <HsButton variant="primary" onClick={view.onPickRelink}>
          {mismatch
            ? ja.import.errors.specifyAnother
            : ja.import.errors.specifySource}
        </HsButton>
        <HsButton variant="secondary" onClick={view.onDismissError}>
          {ja.import.errors.close}
        </HsButton>
      </div>
    </div>
  );
}

/** #264: project transcription.settings -> 採譜オプション restore mapping. */
import { describe, expect, it } from "vitest";
import {
  buildTranscriptionParams,
  invalidSelectionRange,
  transcriptionOptionsFromSettings,
} from "./transcriptionParams";
import { DEFAULT_TRANSCRIPTION_OPTIONS } from "./types";
import type { LoadedAudio } from "./types";

function audioOf(fileName: string): LoadedAudio {
  return {
    ref: { kind: "file", file: new File([], fileName), name: fileName },
    fileName,
    format: "wav",
    sizeBytes: 0,
    durationSeconds: 8,
    sampleRate: 22050,
    peaks: [],
    mediaSource: { kind: "blob", blob: new Blob() },
  };
}

describe("buildTranscriptionParams", () => {
  it("#305: sends the user file name as displayName, not the staged path", () => {
    const p = buildTranscriptionParams(
      audioOf("take.wav"),
      DEFAULT_TRANSCRIPTION_OPTIONS,
      "C:/Temp/hornscribe-dev/staged-1-take.wav",
    );
    expect(p.audioPath).toBe("C:/Temp/hornscribe-dev/staged-1-take.wav");
    expect(p.displayName).toBe("take.wav");
  });

  it("#305: displayName is the file name even for a path ref", () => {
    const audio = audioOf("song.wav");
    audio.ref = { kind: "path", path: "C:/music/song.wav", name: "song.wav" };
    const p = buildTranscriptionParams(audio, DEFAULT_TRANSCRIPTION_OPTIONS);
    expect(p.audioPath).toBe("C:/music/song.wav");
    expect(p.displayName).toBe("song.wav");
  });

  it("#346: an inverted selection is NOT widened to the full span", () => {
    const p = buildTranscriptionParams(audioOf("take.wav"), {
      ...DEFAULT_TRANSCRIPTION_OPTIONS,
      range: "selection",
      selectionStartSec: 5,
      selectionEndSec: 2,
    });
    // The clamped pair travels as-is — the engine rejects it
    // explicitly rather than transcribing a different range.
    expect(p.range).toBe("selection");
    expect(p.selectionStartSec).toBe(5);
    expect(p.selectionEndSec).toBe(2);
  });

  it("#346: clamps each bound into [0, duration] without fixing order", () => {
    const p = buildTranscriptionParams(audioOf("take.wav"), {
      ...DEFAULT_TRANSCRIPTION_OPTIONS,
      range: "selection",
      selectionStartSec: -3,
      selectionEndSec: 100,
    });
    expect(p.selectionStartSec).toBe(0);
    expect(p.selectionEndSec).toBe(8);
  });
});

describe("invalidSelectionRange (#346)", () => {
  const sel = (s: number | null, e: number | null) => ({
    range: "selection" as const,
    selectionStartSec: s,
    selectionEndSec: e,
  });

  it("is false for 全曲 mode and for a valid pair", () => {
    expect(invalidSelectionRange({ range: "all" }, 8)).toBe(false);
    expect(invalidSelectionRange(sel(2, 5), 8)).toBe(false);
  });

  it("is true for inverted, equal, and fully-out-of-span pairs", () => {
    expect(invalidSelectionRange(sel(5, 2), 8)).toBe(true);
    expect(invalidSelectionRange(sel(4, 4), 8)).toBe(true);
    // Both clamp to the same edge (8s file).
    expect(invalidSelectionRange(sel(9, 20), 8)).toBe(true);
  });

  it("unset fields default to the full span (valid)", () => {
    expect(invalidSelectionRange(sel(null, null), 8)).toBe(false);
    expect(invalidSelectionRange(sel(2, null), 8)).toBe(false);
    expect(invalidSelectionRange(sel(null, 4), 8)).toBe(false);
  });
});

